#!/usr/bin/env bash
set -Eeuo pipefail

ROOT="${1:-/root/hyper-hosting-panel}"
SID="${2:-25}"
PUBLIC_IP="90.189.208.25"
LAN_IP="192.168.0.179"

SRC_CTL="$ROOT/cs16-panel/bin/hyper-cs16-ctl"
LIVE_CTL="/usr/local/sbin/hyper-cs16-ctl"
CSTRIKE="/srv/hyper-cs16/servers/${SID}/cstrike"
FASTDL="/srv/hyper-cs16/fastdl/${SID}"
NGINX_CONF="/etc/nginx/conf.d/00-hyper-cs16-fastdl-ip.conf"
STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="/root/hyper-cs16-fastdl-v51-${STAMP}"

[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "[ERROR] run as root"; exit 1; }
[[ -f "$SRC_CTL" ]] || { echo "[ERROR] missing $SRC_CTL"; exit 2; }
[[ -d "$CSTRIKE" ]] || { echo "[ERROR] missing $CSTRIKE"; exit 2; }

mkdir -p "$BACKUP"
cp -a "$SRC_CTL" "$BACKUP/hyper-cs16-ctl.repo"
[[ -f "$LIVE_CTL" ]] && cp -a "$LIVE_CTL" "$BACKUP/hyper-cs16-ctl.live"
[[ -f "$CSTRIKE/server.cfg" ]] && cp -a "$CSTRIKE/server.cfg" "$BACKUP/server.cfg"
for f in fastdl.cfg server_download_fix.cfg SAFE_DOWNLOAD_MODE.cfg ENABLE_FASTDL_AFTER_VERIFY.cfg; do
  [[ -f "$CSTRIKE/$f" ]] && cp -a "$CSTRIKE/$f" "$BACKUP/$f"
done
[[ -f "$NGINX_CONF" ]] && cp -a "$NGINX_CONF" "$BACKUP/nginx-fastdl.conf"

echo "================================================================"
echo " HYPER-HOST FASTDL v5.1"
echo " Fixes local allowed_exts conflict + cleans server.cfg"
echo "================================================================"

echo "[1/9] Clean server.cfg before any FastDL controller call..."
CLEANER="$(mktemp)"
echo '' | base64 -d > "$CLEANER"
python3 "$CLEANER" "$CSTRIKE" "$SID"
rm -f "$CLEANER"

echo "[2/9] Patch controller with independent FastDL copy helper..."
PATCHER="$(mktemp)"
echo '' | base64 -d > "$PATCHER"
python3 "$PATCHER" "$SRC_CTL"
python3 -m py_compile "$SRC_CTL"
install -m 0755 "$SRC_CTL" "$LIVE_CTL"
python3 -m py_compile "$LIVE_CTL"
rm -f "$PATCHER"

echo "[3/9] Install and verify IP-only nginx FastDL route..."
cat >"$NGINX_CONF" <<'EOF'
server {
    listen 80;
    listen [::]:80;
    server_name 90.189.208.25;

    access_log /var/log/nginx/hyper-cs16-fastdl-access.log;
    error_log  /var/log/nginx/hyper-cs16-fastdl-error.log warn;

    location ^~ /fastdl/ {
        alias /srv/hyper-cs16/fastdl/;
        autoindex off;
        default_type application/octet-stream;
        add_header Cache-Control "public, max-age=86400" always;
        add_header X-Hyper-FastDL "1" always;
    }

    location / { return 404; }
}
EOF
nginx -t
systemctl reload nginx
if command -v ufw >/dev/null 2>&1; then ufw allow 80/tcp >/dev/null 2>&1 || true; fi

echo "[4/9] Rebuild FastDL mirror..."
"$LIVE_CTL" fastdl-sync "$SID"

echo "[5/9] Verify all BSP maps are mirrored..."
SERVER_MAPS="$(find "$CSTRIKE/maps" -maxdepth 1 -type f -iname '*.bsp' -printf '%f\n' 2>/dev/null | sort)"
FASTDL_MAPS="$(find "$FASTDL/maps" -maxdepth 1 -type f -iname '*.bsp' -printf '%f\n' 2>/dev/null | sort)"
echo "Server BSP: $(printf '%s\n' "$SERVER_MAPS" | sed '/^$/d' | wc -l)"
echo "FastDL BSP: $(printf '%s\n' "$FASTDL_MAPS" | sed '/^$/d' | wc -l)"
MISSING="$(comm -23 <(printf '%s\n' "$SERVER_MAPS") <(printf '%s\n' "$FASTDL_MAPS") | sed '/^$/d' || true)"
if [[ -n "$MISSING" ]]; then
  echo "[ERROR] BSP missing from FastDL:"
  echo "$MISSING"
  exit 20
fi

echo "[6/9] Verify a real FastDL file returns HTTP 200..."
PROBE="$(find "$FASTDL/maps" -maxdepth 1 -type f -iname 'zm_*.bsp' -print -quit 2>/dev/null || true)"
[[ -n "$PROBE" ]] || PROBE="$(find "$FASTDL" -type f -print -quit 2>/dev/null || true)"
[[ -n "$PROBE" ]] || { echo "[ERROR] FastDL mirror is empty"; exit 21; }
REL="${PROBE#"$FASTDL/"}"
CODE="$(curl -sS --connect-timeout 3 --max-time 12 -H "Host: $PUBLIC_IP" -o /tmp/hh-fastdl-v51.bin -w '%{http_code}' "http://127.0.0.1/fastdl/$SID/$REL" || true)"
echo "Probe: $REL"
echo "Local HTTP: $CODE"
[[ "$CODE" == "200" ]] || { echo "[ERROR] nginx FastDL did not return 200"; exit 22; }
echo "Downloaded bytes: $(wc -c </tmp/hh-fastdl-v51.bin)"
rm -f /tmp/hh-fastdl-v51.bin

echo "[7/9] Restart game server with the clean config..."
systemctl restart "hyper-cs16@${SID}.service"
sleep 4
systemctl is-active "hyper-cs16@${SID}.service"

echo "[8/9] Verify runtime FastDL cvars..."
"$LIVE_CTL" rcon "$SID" "sv_downloadurl" || true
"$LIVE_CTL" rcon "$SID" "sv_allowdownload" || true
"$LIVE_CTL" rcon "$SID" "sv_allow_dlfile" || true

echo "[9/9] Final FastDL status and server.cfg audit..."
"$LIVE_CTL" fastdl-status "$SID" || true

python3 - "$CSTRIKE/server.cfg" <<'PY'
from pathlib import Path
import re,sys
p=Path(sys.argv[1])
raw=p.read_bytes()
txt=raw.decode('utf-8','ignore')
print("server.cfg bytes:",len(raw))
print("real LF:",raw.count(b'\n'))
print("literal \\n:",raw.count(b'\\n'))
print("logical lines:",len(txt.splitlines()))
print("FastDL blocks:",len(re.findall(r'(?im)^\s*// HYPER-HOST FASTDL BEGIN\s*$',txt)))
print("sv_downloadurl:",len(re.findall(r'(?im)^\s*sv_downloadurl\b',txt)))
print("sv_lan:",len(re.findall(r'(?im)^\s*sv_lan\b',txt)))
PY

PUBLIC_CODE="$(curl -sS --connect-timeout 3 --max-time 10 -o /dev/null -w '%{http_code}' "http://$PUBLIC_IP/fastdl/$SID/$REL" || true)"
echo "Public-IP self-test: $PUBLIC_CODE"
if [[ "$PUBLIC_CODE" != "200" ]]; then
  echo "[WARN] Local HTTP is 200, but public-IP self-test is $PUBLIC_CODE."
  echo "       If outside clients also fail, forward TCP 80 -> $LAN_IP:80 on the router."
fi

echo
echo "================================================================"
echo " [SUCCESS] FASTDL v5.1 INSTALLED"
echo "================================================================"
echo "FastDL URL: http://$PUBLIC_IP/fastdl/$SID/"
echo "Backup: $BACKUP"
echo "server.cfg is normalized and contains one FastDL block."
